-- SkillQuest: detailed lesson content. Safe to run more than once (it only updates text).
USE skillquest;

-- =====================================================================
-- React Fundamentals
-- =====================================================================
SET @c = (SELECT id FROM courses WHERE title = 'React Fundamentals');
UPDATE lessons SET content = 'React builds user interfaces out of components: small, reusable pieces that each describe one part of the screen. A component is simply a JavaScript function that returns JSX, a syntax that looks like HTML but lives inside JavaScript.\n\nKey points:\n• Component names start with a capital letter (CourseCard, not courseCard).\n• A component can contain other components, forming a tree: App > Header > Button.\n• Reusing components keeps your code short and your design consistent.\n• JSX must return one parent element; use <> ... </> to group siblings.\n\nExample:\nfunction CourseCard() {\n  return <h3>React Fundamentals</h3>;\n}\n\nRemember: if a piece of UI appears more than once, it should probably be its own component.' WHERE course_id = @c AND sort_order = 1;
UPDATE lessons SET content = 'Props and state are the two ways a component gets data. Props are inputs passed from a parent and are read-only. State is data that a component owns and can change over time; when state changes, React re-renders the component automatically.\n\nKey points:\n• Props flow one way: parent to child.\n• Never modify props inside the child component.\n• useState returns the current value and a function to update it.\n• Always update state with the setter function, never by changing the variable directly.\n\nExample:\nfunction Counter() {\n  const [count, setCount] = useState(0);\n  return <button onClick={() => setCount(count + 1)}>Clicked {count}</button>;\n}\n\nRemember: props are what you are given, state is what you keep.' WHERE course_id = @c AND sort_order = 2;
UPDATE lessons SET content = 'Some work must happen outside rendering, such as calling an API, setting a timer or updating the page title. These are called side effects, and useEffect is the hook for them. React runs the effect after the component renders.\n\nKey points:\n• The second argument is the dependency array and controls when the effect re-runs.\n• An empty array [] means run once, after the first render.\n• Add every value the effect uses to the dependency array.\n• Return a cleanup function to stop timers or subscriptions.\n\nExample:\nuseEffect(() => {\n  fetch("/api/courses")\n    .then(res => res.json())\n    .then(setCourses);\n}, []);\n\nRemember: CourseList in SkillQuest uses exactly this pattern to load courses when it first appears.' WHERE course_id = @c AND sort_order = 3;
UPDATE lessons SET content = 'Most apps display collections: courses, lessons, quiz questions. In React you turn an array of data into a list of components with the map() method. Every item needs a unique, stable key so React can work out which items were added, removed or moved.\n\nKey points:\n• Use a database id as the key whenever you have one.\n• Do not use the array index as a key if the list can be reordered or filtered.\n• The key goes on the outermost element returned inside map().\n• Keys are not passed to the component as props.\n\nExample:\n{courses.map(c => (\n  <CourseCard key={c.id} course={c} />\n))}\n\nRemember: a missing key causes a console warning and can lead to wrong items being updated.' WHERE course_id = @c AND sort_order = 4;
UPDATE lessons SET content = 'React handles user actions through event props such as onClick, onChange and onSubmit. In a controlled input, the value lives in state and every keystroke updates that state, so React is always the single source of truth for what the form contains.\n\nKey points:\n• Pass a function to the event prop; do not call it (onClick={save}, not onClick={save()}).\n• e.target.value gives the current text of an input.\n• Call e.preventDefault() in onSubmit to stop the page from reloading.\n• One state object can hold all fields of a form.\n\nExample:\nconst [name, setName] = useState("");\n<input value={name} onChange={e => setName(e.target.value)} />\n\nRemember: the login and register form in SkillQuest is a controlled form.' WHERE course_id = @c AND sort_order = 5;
UPDATE lessons SET content = 'When two components need the same data, neither should own it alone. Move the state to their closest common parent and pass it down as props. Children ask the parent to change it by calling functions that the parent passes in.\n\nKey points:\n• Keep state as close as possible to where it is used, but high enough to be shared.\n• Pass both the value and the updater function down as props.\n• This keeps one source of truth and avoids out-of-sync screens.\n• If many levels need the data, consider React Context.\n\nExample:\nfunction App() {\n  const [stats, setStats] = useState(null);\n  return <Dashboard stats={stats} onStats={setStats} />;\n}\n\nRemember: in SkillQuest, App holds the user and XP stats so the header, dashboard and quiz always agree.' WHERE course_id = @c AND sort_order = 6;

-- =====================================================================
-- Spring MVC in Practice
-- =====================================================================
SET @c = (SELECT id FROM courses WHERE title = 'Spring MVC in Practice');
UPDATE lessons SET content = 'In Spring MVC, a controller receives an HTTP request, runs your logic and returns a response. A class marked @RestController returns data (usually JSON) instead of web pages. Each method is mapped to a URL and an HTTP method.\n\nKey points:\n• @RequestMapping on the class sets the base path, for example /api/courses.\n• @GetMapping, @PostMapping, @PutMapping and @DeleteMapping match the HTTP method.\n• @PathVariable reads a value from the URL; @RequestParam reads query parameters.\n• Spring converts returned objects to JSON automatically using Jackson.\n\nExample:\n@RestController\n@RequestMapping("/api/courses")\npublic class CourseController {\n  @GetMapping\n  public List<Course> list() { return courses.findAll(); }\n}\n\nRemember: controllers should stay thin and hand real work to services.' WHERE course_id = @c AND sort_order = 1;
UPDATE lessons SET content = 'JPA lets you work with database rows as Java objects. You describe a table with an @Entity class and Spring Data JPA generates the repository code for you, so you rarely write SQL by hand.\n\nKey points:\n• @Entity marks a class as a table; @Id marks the primary key.\n• @Column maps a field to a column with a different name, such as password_hash.\n• A repository interface extending JpaRepository gives save, findById, findAll and delete for free.\n• Derived queries are built from method names: findByEmail, findTop10ByOrderByXpDesc.\n\nExample:\npublic interface UserRepository extends JpaRepository<User, Long> {\n  Optional<User> findByEmail(String email);\n}\n\nRemember: this is why SkillQuest has almost no SQL in the Java code.' WHERE course_id = @c AND sort_order = 2;
UPDATE lessons SET content = 'Spring Security protects your endpoints. Every request passes through a chain of filters that decide who the caller is and whether they are allowed in. You configure the rules in a SecurityFilterChain bean.\n\nKey points:\n• Passwords must be hashed with BCrypt, never stored as plain text.\n• permitAll() opens a route to everyone; authenticated() requires a logged-in user.\n• After login the server keeps the user in a session identified by a cookie.\n• An unauthenticated request should return 401, not a login page, when the client is a React app.\n\nExample:\nhttp.authorizeHttpRequests(a -> a\n  .requestMatchers("/api/auth/**").permitAll()\n  .anyRequest().authenticated());\n\nRemember: in SkillQuest anyone can browse courses, but lessons, quizzes and the leaderboard need a login.' WHERE course_id = @c AND sort_order = 3;
UPDATE lessons SET content = 'Clients send data to your API as JSON in the request body. Spring turns that JSON into a Java object for you, and you must check it before trusting it. Never assume the input is valid.\n\nKey points:\n• @RequestBody converts JSON into a Java object or record.\n• Check required fields and lengths, and return 400 Bad Request when they are wrong.\n• Use 409 Conflict when the data clashes with existing data, such as a duplicate email.\n• Return a small JSON message so the frontend can show a helpful error.\n\nExample:\n@PostMapping("/register")\npublic ResponseEntity<?> register(@RequestBody RegisterRequest r) {\n  if (r.password().length() < 6)\n    return ResponseEntity.badRequest().body(Map.of("error", "Password too short"));\n  ...\n}\n\nRemember: validate on the server even if the frontend already validates.' WHERE course_id = @c AND sort_order = 4;
UPDATE lessons SET content = 'Instead of creating the objects it needs with new, a class asks Spring for them. Spring builds each object once (a bean) and injects it where needed. This keeps classes loosely coupled and makes testing easy because you can swap in fake versions.\n\nKey points:\n• Constructor injection is the recommended style.\n• Classes marked @Service, @Repository, @Controller or @Component are picked up automatically.\n• @Bean methods in a @Configuration class register objects you build yourself.\n• Beans are singletons by default: one shared instance.\n\nExample:\n@RestController\npublic class CourseController {\n  private final CourseRepository courses;\n  public CourseController(CourseRepository courses) { this.courses = courses; }\n}\n\nRemember: if you write new CourseRepository() yourself, you have lost the benefit of Spring.' WHERE course_id = @c AND sort_order = 5;
UPDATE lessons SET content = 'A good Spring application is split into layers, each with one job. Requests flow down from controller to service to repository, and responses flow back up. This makes code easier to read, test and change.\n\nKey points:\n• Controller: handles HTTP, reads input and returns responses.\n• Service: holds business rules such as awarding XP or checking enrollment.\n• Repository: talks to the database only.\n• Entity: represents a table row; DTOs or records shape what the API sends back.\n\nExample flow:\nPOST /api/lessons/5/complete\n  LessonController -> GamificationService.addXp() -> UserRepository.save()\n\nRemember: if a controller method is getting long, move the logic into a service.' WHERE course_id = @c AND sort_order = 6;

-- =====================================================================
-- MySQL for Developers
-- =====================================================================
SET @c = (SELECT id FROM courses WHERE title = 'MySQL for Developers');
UPDATE lessons SET content = 'A good database design starts with identifying the things you store (users, courses, lessons) and how they relate. Each thing becomes a table, each property becomes a column and each row is one record.\n\nKey points:\n• Every table needs a primary key, often an AUTO_INCREMENT id.\n• Choose the smallest suitable data type: INT for counts, VARCHAR for short text, TEXT for long text, DATE for dates.\n• Use NOT NULL for required columns and UNIQUE for values like email.\n• Foreign keys link tables and stop you from creating orphan records.\n\nExample:\nCREATE TABLE lessons (\n  id BIGINT AUTO_INCREMENT PRIMARY KEY,\n  course_id BIGINT NOT NULL,\n  title VARCHAR(200) NOT NULL,\n  FOREIGN KEY (course_id) REFERENCES courses(id)\n);\n\nRemember: a lesson cannot exist without a course, and the foreign key enforces that.' WHERE course_id = @c AND sort_order = 1;
UPDATE lessons SET content = 'Without an index, MySQL reads every row to find a match, which is called a full table scan. An index is a sorted structure that lets MySQL jump straight to the matching rows, like the index at the back of a book.\n\nKey points:\n• Primary keys and UNIQUE columns are indexed automatically.\n• Index columns you often use in WHERE, JOIN and ORDER BY.\n• Indexes speed up reads but slow down writes slightly and use extra disk space.\n• EXPLAIN shows whether a query is using an index.\n\nExample:\nCREATE INDEX idx_enrollments_user ON enrollments(user_id);\nEXPLAIN SELECT * FROM enrollments WHERE user_id = 1;\n\nRemember: do not index everything, only the columns your queries really use.' WHERE course_id = @c AND sort_order = 2;
UPDATE lessons SET content = 'Data is split across tables, and a JOIN brings it back together by matching a column in one table to a column in another. Usually you match a foreign key to a primary key.\n\nKey points:\n• INNER JOIN returns only rows that match in both tables.\n• LEFT JOIN keeps all rows from the left table, with NULL where there is no match.\n• Give tables short aliases (e, c) to keep queries readable.\n• Always include the ON condition, or you create a huge cross product.\n\nExample:\nSELECT c.title, e.progress_percent\nFROM enrollments e\nJOIN courses c ON c.id = e.course_id\nWHERE e.user_id = 1;\n\nRemember: this is the kind of query behind the My Courses list on the SkillQuest dashboard.' WHERE course_id = @c AND sort_order = 3;
UPDATE lessons SET content = 'A transaction groups several statements into one all-or-nothing unit. If anything fails halfway, you roll everything back and the database stays consistent. InnoDB, the default MySQL engine, supports transactions.\n\nKey points:\n• ACID: Atomicity, Consistency, Isolation, Durability.\n• START TRANSACTION begins, COMMIT saves and ROLLBACK undoes.\n• Use transactions when several updates must stay in step, such as saving a lesson completion and adding XP.\n• In Spring you get the same effect with the @Transactional annotation.\n\nExample:\nSTART TRANSACTION;\nINSERT INTO lesson_completions (user_id, lesson_id) VALUES (1, 5);\nUPDATE users SET xp = xp + 20 WHERE id = 1;\nCOMMIT;\n\nRemember: without a transaction, a crash between the two statements could save the lesson but lose the XP.' WHERE course_id = @c AND sort_order = 4;
UPDATE lessons SET content = 'Normalisation is the process of organising tables so that each fact is stored once. It prevents repeated data, which wastes space and causes mistakes when one copy is updated and another is forgotten.\n\nKey points:\n• First normal form: each column holds one value, not a list.\n• Second normal form: every column depends on the whole primary key.\n• Third normal form: columns depend only on the key, not on other columns.\n• Split repeated data into its own table and link it with a foreign key.\n\nExample:\nInstead of storing the badge name and icon on every user row, SkillQuest keeps them once in badges and stores only badge_code in user_badges.\n\nRemember: normalise to avoid duplication, but do not over-split; sometimes a little repetition is fine for speed.' WHERE course_id = @c AND sort_order = 5;

-- =====================================================================
-- Java Programming Basics
-- =====================================================================
SET @c = (SELECT id FROM courses WHERE title = 'Java Programming Basics');
UPDATE lessons SET content = 'A variable is a named container for a value. Java is statically typed, which means you must declare the type of every variable and the compiler checks that you use it correctly. This catches many mistakes before the program even runs.\n\nKey points:\n• Primitive types: int (whole numbers), double (decimals), boolean (true or false), char (one character).\n• String is a class, not a primitive, and is written with double quotes.\n• Use final to make a value that can never change.\n• Variable names use camelCase, for example totalXp.\n\nExample:\nint age = 20;\ndouble price = 99.5;\nboolean active = true;\nString name = "Asha";\nfinal int MAX_LEVEL = 50;\n\nRemember: choose the type that fits the data, because int cannot hold decimals.' WHERE course_id = @c AND sort_order = 1;
UPDATE lessons SET content = 'Control flow decides which code runs and how many times. Conditions choose a path; loops repeat work. These are the building blocks of every program.\n\nKey points:\n• if, else if and else choose between paths using boolean conditions.\n• Use == for numbers and .equals() for Strings.\n• for loops are best when you know how many times to repeat; while loops repeat until a condition changes.\n• break leaves a loop early and continue skips to the next round.\n\nExample:\nint xp = 250;\nif (xp >= 200) {\n  System.out.println("Level 3");\n} else {\n  System.out.println("Keep going");\n}\nfor (int i = 1; i <= 3; i++) {\n  System.out.println("Lesson " + i);\n}\n\nRemember: comparing Strings with == checks identity, not content.' WHERE course_id = @c AND sort_order = 2;
UPDATE lessons SET content = 'Object-oriented programming models real things as objects. A class is the blueprint, and each object created from it is an instance with its own data. Classes combine fields (data) and methods (behaviour).\n\nKey points:\n• Use the new keyword to create an object.\n• A constructor sets up the initial values.\n• Make fields private and expose them through getters and setters (encapsulation).\n• Inheritance (extends) lets one class reuse another, and interfaces define what a class must do.\n\nExample:\npublic class Course {\n  private String title;\n  public Course(String title) { this.title = title; }\n  public String getTitle() { return title; }\n}\nCourse c = new Course("Java Basics");\n\nRemember: Spring entities such as User and Course in SkillQuest are exactly this kind of class.' WHERE course_id = @c AND sort_order = 3;
UPDATE lessons SET content = 'Real programs handle groups of values. The Java Collections Framework gives you ready-made structures so you do not have to build them yourself. Choosing the right one makes code simpler and faster.\n\nKey points:\n• List (ArrayList): ordered, allows duplicates, access by position.\n• Set (HashSet): no duplicates, no guaranteed order.\n• Map (HashMap): stores key-value pairs and looks up by key quickly.\n• Use generics, such as List<String>, so the compiler checks the item type.\n\nExample:\nList<String> names = new ArrayList<>();\nnames.add("Asha");\nMap<String, Integer> xp = new HashMap<>();\nxp.put("Asha", 220);\nSystem.out.println(xp.get("Asha"));\n\nRemember: a quiz answer sheet is naturally a Map from question id to selected option.' WHERE course_id = @c AND sort_order = 4;

-- =====================================================================
-- HTML and CSS Essentials
-- =====================================================================
SET @c = (SELECT id FROM courses WHERE title = 'HTML and CSS Essentials');
UPDATE lessons SET content = 'HTML describes the structure and meaning of a page. Semantic elements tell browsers, search engines and screen readers what each part is for, instead of using generic div tags everywhere.\n\nKey points:\n• header, nav, main, section, article, aside and footer describe page regions.\n• Use h1 to h6 in order to create a clear outline; one h1 per page.\n• Always add alt text to images and label text to form inputs.\n• Use button for actions and a for links.\n\nExample:\n<header>\n  <nav><a href="/courses">Courses</a></nav>\n</header>\n<main>\n  <article><h1>React Fundamentals</h1></article>\n</main>\n\nRemember: good semantics make a page accessible and easier to style.' WHERE course_id = @c AND sort_order = 1;
UPDATE lessons SET content = 'CSS controls how HTML looks. A selector chooses which elements to style, and declarations inside braces set the properties. Every element is drawn as a rectangular box, and understanding that box is the key to layout.\n\nKey points:\n• Selectors: element (p), class (.card), id (#menu) and descendant (nav a).\n• Specificity decides which rule wins: id beats class, class beats element.\n• The box model from inside out: content, padding, border, margin.\n• box-sizing: border-box includes padding and border in the width you set.\n\nExample:\n.card {\n  padding: 16px;\n  border: 1px solid #ccc;\n  border-radius: 12px;\n  margin-bottom: 16px;\n}\n\nRemember: padding is space inside the border, margin is space outside it.' WHERE course_id = @c AND sort_order = 2;
UPDATE lessons SET content = 'Flexbox is a layout system for arranging items in one direction, either a row or a column. It handles spacing, alignment and wrapping without floats or fixed widths, and it is used in almost every modern interface.\n\nKey points:\n• Set display: flex on the parent container.\n• flex-direction chooses row or column.\n• justify-content aligns items along the main axis; align-items aligns across it.\n• gap adds space between items; flex-wrap lets them wrap onto new lines.\n\nExample:\nnav {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 8px;\n}\n\nRemember: the SkillQuest header and navigation bar are laid out with flexbox.' WHERE course_id = @c AND sort_order = 3;
UPDATE lessons SET content = 'A responsive page looks good on phones, tablets and desktops. Instead of fixed pixel layouts, you use flexible sizes and rules that change with the screen width.\n\nKey points:\n• Add <meta name="viewport" content="width=device-width, initial-scale=1"> to the head.\n• Use relative units: %, rem, vw, and max-width instead of fixed widths.\n• Media queries apply styles only at certain screen sizes.\n• Design for mobile first, then add rules for larger screens.\n\nExample:\n.player { display: grid; grid-template-columns: 240px 1fr; }\n@media (max-width: 700px) {\n  .player { grid-template-columns: 1fr; }\n}\n\nRemember: the lesson page in SkillQuest stacks its sidebar above the content on small screens using exactly this rule.' WHERE course_id = @c AND sort_order = 4;

-- =====================================================================
-- JavaScript Essentials
-- =====================================================================
SET @c = (SELECT id FROM courses WHERE title = 'JavaScript Essentials');
UPDATE lessons SET content = 'JavaScript is dynamically typed: a variable can hold any type and the type is decided at run time. Modern code uses let and const, which are scoped to the block they are declared in.\n\nKey points:\n• const for values that are never reassigned; let for values that change; avoid var.\n• Types: string, number, boolean, null, undefined, object, array and function.\n• Use === to compare without type conversion; == can give surprising results.\n• Template literals use backticks and let you insert values with ${...}.\n\nExample:\nconst name = "Asha";\nlet score = 0;\nscore = score + 20;\nconsole.log(`${name} has ${score} XP`);\n\nRemember: const stops reassignment, but the contents of a const array or object can still change.' WHERE course_id = @c AND sort_order = 1;
UPDATE lessons SET content = 'Functions package reusable logic. You can declare them with the function keyword or write them as arrow functions, which are shorter and are used everywhere in React.\n\nKey points:\n• Parameters receive input and return sends a value back.\n• Default values: function greet(name = "friend").\n• Arrow functions: const add = (a, b) => a + b;\n• Functions are values, so you can pass them to other functions as callbacks.\n\nExample:\nconst level = xp => Math.floor(xp / 100) + 1;\nconsole.log(level(220)); // 3\n\nRemember: this exact function calculates levels in the SkillQuest demo.' WHERE course_id = @c AND sort_order = 2;
UPDATE lessons SET content = 'Arrays hold ordered lists of values. Instead of writing loops by hand, modern JavaScript uses array methods that describe what you want. They return new arrays and leave the original unchanged.\n\nKey points:\n• map(fn) transforms every item into something else.\n• filter(fn) keeps only the items that pass a test.\n• find(fn) returns the first match; includes(x) checks if a value is present.\n• reduce(fn, start) combines all items into one value, such as a total.\n\nExample:\nconst xp = [20, 20, 30];\nconst doubled = xp.map(n => n * 2);\nconst big = xp.filter(n => n >= 25);\nconst total = xp.reduce((sum, n) => sum + n, 0); // 70\n\nRemember: React uses map to turn data into lists of components.' WHERE course_id = @c AND sort_order = 3;
UPDATE lessons SET content = 'Operations like fetching data take time, and JavaScript does not freeze while waiting. A promise represents a value that will arrive later. async and await let you write code that waits for promises while still reading top to bottom.\n\nKey points:\n• A promise is pending, then either fulfilled or rejected.\n• await can only be used inside an async function.\n• Wrap await calls in try/catch to handle errors such as a failed network request.\n• fetch returns a promise; call response.json() to read the data.\n\nExample:\nasync function loadCourses() {\n  try {\n    const res = await fetch("/api/courses");\n    return await res.json();\n  } catch (e) {\n    console.log("Failed", e);\n  }\n}\n\nRemember: this is how the React frontend talks to the Spring backend.' WHERE course_id = @c AND sort_order = 4;

-- =====================================================================
-- Git and GitHub
-- =====================================================================
SET @c = (SELECT id FROM courses WHERE title = 'Git and GitHub');
UPDATE lessons SET content = 'Version control tracks every change you make to a project. You can see who changed what and when, go back to an older version and work with other people without overwriting each other. Git is the most widely used system.\n\nKey points:\n• A repository (repo) is a project folder with its full history.\n• Git is distributed: every developer has a complete copy.\n• Files move through three areas: working directory, staging area and committed history.\n• GitHub, GitLab and Bitbucket host repositories online.\n\nExample:\ngit init\ngit status\n\nRemember: commit early and often; small commits are easy to understand and undo.' WHERE course_id = @c AND sort_order = 1;
UPDATE lessons SET content = 'A commit is a snapshot of your project with a message explaining the change. A branch is a separate line of development, so you can build a feature without touching the stable main branch.\n\nKey points:\n• git add stages changes; git commit saves them.\n• Write messages that say what and why, for example "Add quiz scoring".\n• git switch -c name creates and moves to a new branch.\n• git log shows history; git diff shows what changed.\n\nExample:\ngit add .\ngit commit -m "Add lesson page"\ngit switch -c feature/quiz\n\nRemember: never work directly on main for new features; use a branch.' WHERE course_id = @c AND sort_order = 2;
UPDATE lessons SET content = 'When a feature is finished you merge its branch back into main. Git combines the changes automatically, unless two branches edited the same lines. Then you get a merge conflict and must decide what the final text should be.\n\nKey points:\n• Run git switch main, then git merge feature/quiz.\n• Conflicts appear in the file between <<<<<<<, ======= and >>>>>>> markers.\n• Edit the file to keep the correct result, remove the markers, then git add and git commit.\n• Pulling often keeps conflicts small.\n\nExample:\ngit switch main\ngit merge feature/quiz\n\nRemember: a conflict is normal, not an error; it simply means Git needs a human decision.' WHERE course_id = @c AND sort_order = 3;
UPDATE lessons SET content = 'GitHub stores your repository online so others can see it and contribute. You work on a branch, push it, and open a pull request (PR). Teammates review the change and discuss it before it is merged into main.\n\nKey points:\n• git remote add origin <url> connects your local repo to GitHub.\n• git push -u origin branch uploads your branch.\n• A good PR has a clear title, a short description and small changes.\n• Issues track bugs and tasks; a README explains the project.\n\nExample:\ngit push -u origin feature/quiz\n(then click Compare and pull request on GitHub)\n\nRemember: add a README and a .gitignore to every project before you publish it.' WHERE course_id = @c AND sort_order = 4;

-- =====================================================================
-- REST API Design
-- =====================================================================
SET @c = (SELECT id FROM courses WHERE title = 'REST API Design');
UPDATE lessons SET content = 'REST is a style for designing web APIs around resources: things such as courses, lessons and users. Each resource has a URL, and you act on it with standard HTTP methods. Clean URLs make an API easy to guess and use.\n\nKey points:\n• Use nouns, not verbs: /courses, not /getCourses.\n• Use plural names and nest for relationships: /courses/5/lessons.\n• Identify one item by id: /courses/5.\n• Use query parameters for filtering: /courses?level=BEGINNER.\n\nExample:\nGET /api/courses\nGET /api/courses/5\nGET /api/courses/5/lessons\n\nRemember: the action comes from the HTTP method, not from the URL.' WHERE course_id = @c AND sort_order = 1;
UPDATE lessons SET content = 'HTTP defines methods that say what you want to do with a resource. Using them correctly makes your API predictable, and browsers, caches and tools rely on these rules.\n\nKey points:\n• GET reads data and must never change anything.\n• POST creates a new resource or triggers an action.\n• PUT replaces a resource; PATCH changes part of it.\n• DELETE removes a resource.\n• GET, PUT and DELETE are idempotent: repeating them gives the same result.\n\nExample:\nPOST /api/enrollments/3         enroll in course 3\nPOST /api/lessons/5/complete    mark lesson 5 done\nGET  /api/me/stats              read my XP and badges\n\nRemember: if a request changes data, it should not be a GET.' WHERE course_id = @c AND sort_order = 2;
UPDATE lessons SET content = 'Every response carries a three-digit status code. It tells the client straight away whether the request worked, and if not, whose fault it was. The first digit gives the category.\n\nKey points:\n• 2xx success: 200 OK, 201 Created, 204 No Content.\n• 4xx client error: 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found, 409 Conflict.\n• 5xx server error: 500 Internal Server Error.\n• 401 means not logged in; 403 means logged in but not allowed.\n\nExample:\nEnrolling twice in SkillQuest returns 409 Conflict with the message "Already enrolled".\n\nRemember: pick the most specific code, and include a short JSON error message.' WHERE course_id = @c AND sort_order = 3;
UPDATE lessons SET content = 'Authentication proves who the caller is; authorization decides what they may do. Since HTTP is stateless, the server needs a way to recognise a user on every request after login.\n\nKey points:\n• Never store plain passwords; store a salted hash such as BCrypt.\n• Session cookies: the server remembers the user and gives the browser a session id.\n• Tokens (JWT): the client sends a signed token in the Authorization header.\n• Always use HTTPS so credentials cannot be read in transit.\n\nExample:\nPOST /api/auth/login   { "email": "a@b.com", "password": "secret1" }\nThe server checks the BCrypt hash, then starts a session.\n\nRemember: SkillQuest uses session cookies, which works well for a single React frontend.' WHERE course_id = @c AND sort_order = 4;

-- =====================================================================
-- Data Structures and Algorithms
-- =====================================================================
SET @c = (SELECT id FROM courses WHERE title = 'Data Structures and Algorithms');
UPDATE lessons SET content = 'Big O notation describes how the running time or memory of an algorithm grows as the input size n grows. It ignores small details and focuses on the shape of the growth, which is what matters for large inputs.\n\nKey points:\n• O(1) constant: the same time for any input, such as reading array[5].\n• O(log n): grows very slowly, such as binary search.\n• O(n): grows in step with the input, such as scanning a list.\n• O(n log n): efficient sorting. O(n^2): nested loops, slow for large n.\n\nExample:\nfor (int x : list) { ... }          // O(n)\nfor (int a : list)\n  for (int b : list) { ... }        // O(n^2)\n\nRemember: drop constants and keep the fastest-growing term, so 3n + 10 is just O(n).' WHERE course_id = @c AND sort_order = 1;
UPDATE lessons SET content = 'Arrays and linked lists both store sequences, but they trade speed in different places. Knowing which operations each makes cheap helps you pick the right structure.\n\nKey points:\n• Array: contiguous memory, O(1) access by index, O(n) insert or delete in the middle.\n• Linked list: nodes point to the next node; O(1) insert at a known position, O(n) to reach the kth item.\n• Dynamic arrays (ArrayList, JavaScript arrays) grow automatically.\n• Arrays are cache-friendly, so they are usually faster in practice.\n\nExample:\nclass Node { int value; Node next; }\n\nRemember: use an array by default and switch to a linked list only when you insert and remove often at the ends.' WHERE course_id = @c AND sort_order = 2;
UPDATE lessons SET content = 'Stacks and queues restrict how you add and remove items, and that restriction is exactly what makes them useful. Many real systems are built on them.\n\nKey points:\n• Stack: last in, first out (LIFO). Operations: push, pop, peek.\n• Queue: first in, first out (FIFO). Operations: enqueue, dequeue.\n• Stack uses: undo, browser back button, matching brackets, function calls.\n• Queue uses: print jobs, task scheduling, breadth-first search.\n\nExample:\nDeque<Integer> stack = new ArrayDeque<>();\nstack.push(1); stack.push(2);\nstack.pop();  // returns 2\n\nRemember: both push and pop on a stack run in O(1).' WHERE course_id = @c AND sort_order = 3;
UPDATE lessons SET content = 'Searching finds an item and sorting puts items in order. Sorted data unlocks much faster searching, which is why sorting is so common.\n\nKey points:\n• Linear search checks every item: O(n), works on unsorted data.\n• Binary search needs sorted data and halves the range each step: O(log n).\n• Simple sorts (bubble, insertion) are O(n^2) and fine for tiny lists.\n• Merge sort and quick sort run in about O(n log n); built-in sort methods use these ideas.\n\nExample:\nint[] a = {2, 5, 8, 12};\nint pos = Arrays.binarySearch(a, 8);  // 2\n\nRemember: searching a million sorted items with binary search takes about 20 steps.' WHERE course_id = @c AND sort_order = 4;
